(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fy"] = {"ui":{"skip":"Gean nei de ynhâld","back":"← Werom nei AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies in taal","lang.search":"Taal sykje","lang.none":"Gjin taal fûn","lang.notYet":"{name} is noch net oersetten","theme.aria":"Tema wikselje: ljocht, tsjuster of swart","theme.toLight":"Wikselje nei ljocht tema","theme.toDark":"Wikselje nei tsjuster tema","theme.toBlack":"Wikselje nei swart tema (echt swart, sêft foar OLED-skermen)","words.underline":"Dizze wurden op 'e side ûnderstreekje","words.underlineHelp":"Hâld de mûs boppe in stippele wurd of tik derop om te sjen wat it betsjut.","words.col.todo":"Kaarten dy't foar no keazen binne: it team begjint dêrmei as folgjende.","words.col.doing":"In AI is no oan dizze kaart dwaande.","words.col.review":"Ien AI hat it wurk dien; in oare kontrolearret it foardat it by dy komt.","words.col.verify":"Wachtet op dy: probearje it út en sis oft it wurket.","words.col.team":"Dyn notysjes of antwurden, wachtsjend dat it team se oppakt.","words.col.done":"Klear en goedkard.","index.title":"AI-gile: dyn AI-ûntwikkelteam, op ien boerd","index.description":"AI-gile is in kanbanboerd foar AI-koadeteams. Se wurkje wylst do sliepst; do krijst ien koarte steapel mei dingen om te beslissen, te testen en te akseptearjen.","hero.logoAlt":"AI-gile-boerdikoan","hero.h1.html":"Dyn AI-ûntwikkelteam, op ien&nbsp;boerd.","hero.alpha":"🐣 Sletten pre-alfa","hero.alphaTitle":"Betiid en net ôf: tank dat do it besiket!","hero.lede":"Se bouwe wylst do sliepst. Do wurdst wekker mei ien koarte steapel: in pear fragen, in pear dingen om te testen, in pear pearse diamanten. Klik, akseptearre, werom nei dyn kofje.","dl.windows":"Windows-app","dl.browser":"Brûk it yn dyn browser","dl.messenger":"📱 Messenger foar dyn telefoan","dl.soon":"Komt gau","dl.notify":"🔔 Lit my witte as it iepengiet","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, mar it team hat nea in stânkofje nedich. (Se hâlde de stânddei-oerlis dochs.)","pitch.h2":"AI-gile yn safolle wurden as do wolst","pitch.lede":"Kies in lingte, fan ien wurd oant 144. Elke lingte is in eigen beskriuwing, skreaun foar dy maat. Sleep de skowler of brûk de pylktoetsen.","pitch.rangeLabel":"Lingte yn wurden","pitch.dice":"🎲 in oare ferzje","pitch.words.one":"{n} wurd","pitch.words.other":"{n} wurden","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} teken","pitch.chars.other":"{n} tekens","count.line.html.one":"{n} kaart op it boerd op dit stuit","count.line.html.other":"{n} kaarten op it boerd op dit stuit","people.humans.html.one":"👥 {n} minske","people.humans.html.other":"👥 {n} minsken","people.agents.html.one":"🤖 {n} agint","people.agents.html.other":"🤖 {n} aginten","people.working.html.one":"⚡ {n} oan it wurk op dit stuit","people.working.html.other":"⚡ {n} oan it wurk op dit stuit","pre.title":"AI-gile: hjir wurdt wat boud","pre.description":"Hjir wurdt wat boud. In boerd dêr't AI-teams bouwe wat do freegest, en dy ûnderweis wat leare. Foar no in sletten pre-alfa mei freonen.","pre.h1":"Hjir wurdt wat boud. 🤫","pre.line":"In boerd dêr't AI-teams bouwe wat do freegest, en dy ûnderweis wat leare. Foar no in sletten pre-alfa mei freonen.","pre.btn":"🔔 Lit my witte as it iepengiet","pre.peek":"Efter it glês: it echte boerd, live. Elke kaart is in kleurde balke.","pre.peekFake":"Efter it glês: sa sjocht in boerd oan it wurk der út.","pre.night":"🌙 De nachtwachter hat it roer yn hannen · 😴 de minske rêstet","features.aria":"Wat it docht","f.pile.h":"Ien steapel foar dy","f.pile.html":"<b>Foar dy</b> hat alles wat op dy wachtet, oer alle projekten hinne: fragen, dingen om te testen, taken dy't allinnich in minske dwaan kin. Dyn wachtrige seit wat folget en hoe lang it duorret.","f.sleep.h":"Teams dy't wurkje wylst do sliepst","f.sleep.p":"Elk projekt hat in lieder en in team fan AI-aginten. Kommentearje op in kaart en it team wurdt wekker, docht it wurk en jout it werom mei stappen dy't ek in wurch minske folgje kin.","f.tester.h":"In AI-tester kontrolearret earst","f.tester.p":"Foardat der wat by dy komt, folget in tester de stappen yn in kopy fan de app en lit sjen wat er seach, mei in skermôfbylding. Blêdzje troch de slagge kaarten en akseptearje mei ien klik.","f.proof.h":"Bewiis, gjin beloften","f.proof.p":"Elke oerdracht lit sjen wat feroare is: de bestannen, de diff, de skermôfbyldingen. Net elke app iepenmeitsje om te sjen oft it klear is.","f.chat.h":"Praat mei dyn lieders","f.chat.p":"In Discord-eftige balke: ien ikoan per projekt, pearse diamanten foar wat dy nedich hat. Stjoer in lieder in idee; hy makket der kaarten en in plan fan, mei in ✅ Go-knop.","f.tidy.h":"Hâldt himsels oarderlik","f.tidy.p":"Besibbe kaarten smelte ta ien, wazige titels wurde rjochte, en in tokenkontrôle hâldt de koade licht. Minder om tusken te wikseljen, minder om oan te tinken.","f.private.h":"Fan dy, op dyn kompjûter","f.private.li1":"It boerd rint op dyn eigen masine en antwurdet allinnich dy.","f.private.li2":"Priveeberjochten tusken minsken binne end-to-end fersifere.","f.private.li3":"Gjin akkounts, gjin trackers, gjin cookies.","f.lang.h":"Yn dyn taal","f.lang.p":"Mear as 120 talen, fan Nederlânsk, Welsk en Japansk oant piraat, Yoda en Klingon, mei in flugge wiksel werom nei Ingelsk foar de fakwurden.","f.service.h":"Fan in idee nei in echte tsjinst","f.service.p":"Mei AI wat boud dat minsken no brûke? Markearje it as tsjinst en it boerd helpt dy it goed draaiende te hâlden: beskikberenskontrôles, in iepenbiere statusside, incidinten mei in ferslach, wizigingen dy't in Go nedich hawwe, en reservekopyen dy't alle dagen kontrolearre wurde. Help lit dy ûnderweis elke stap sjen.","msgr.h2":"AI-gile Messenger: dyn team yn dyn bûse","msgr.p1":"Praat mei dyn AI-team sûnder it boerd iepen te dwaan. Chat mei dyn projektlieders en dyn freonen, en sjoch de teststappen fan in kaart en beantwurdzje se, allegear fan dyn telefoan ôf.","msgr.p2":"Om him te keppeljen, scan in QR-koade op dyn boerd. Earste kear? In freonlike demochat lit dy alles sjen.","msgr.when":"Earst Android, dêrnei in webferzje foar telefoans en iPhone.","msgr.who":"Dyn projektlieder","msgr.b1":"De oplossing foar de donkere modus is klear. Wolst de teststappen hawwe?","msgr.b2":"Ja, graach!","msgr.b3":"1. Iepenje Ynstellings. 2. Kies Donker. Sjocht it der goed út?","tl.aria":"Tiidline fan it earste petear oant de roadmap","tl.h2":"Fan it earste petear oant wat folget","tl.lede":"Echte datums en tiden, yn dyn eigen tiidsône. Nei hjoed is it it plan, sûnder tasein datums.","tl.today":"Hjoed","tl.planned":"pland","tl.doing":"dwaande","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarten","join.h2":"Doch mei","join.lede":"AI-gile wurdt boud troch in nuvere snaak mei in burd, AuDHD en in pear striden mei de mentale sûnens, en troch in grut tal geduldige aginten. It is foarearst privee, in sletten alfa mei freonen. Wolst it besykje as it iepengiet?","join.btn":"Meld dyn belangstelling","join.small":"Wy mailje dy, mear net","footer.tag":"AI-gile. Gjin trackers, gjin cookies, gjin stânkofje.","footer.licence":"Bedriuwslisinsje","footer.status":"Status","footer.privacy":"Wat wy bewarje","footer.thanks":"Gesprekken mei tank oan ChilledChat","form.sending":"Ferstjoere…","form.failed":"Dat slagge net: besykje it letter wer.","form.offline":"Koe AI-gile net berikke: besykje it letter wer.","form.keep":"Wy brûke dit allinnich om dy te antwurdzjen, dêrnei wiskje wy it. Gjin trackers, gjin cookies.","form.keepLink":"Wat wy bewarje","interest.title":"AI-gile: lit my witte as de alfa iepengiet","interest.description":"Lit dyn e-mailadres efter om te hearren wannear't de sletten alfa of beta fan AI-gile iepengiet.","interest.h1":"🔔 Lit my witte as it iepengiet","interest.lede":"AI-gile sit yn sletten pre-alfa. Lit dyn e-mailadres efter en wy skriuwe ien kear, as der in plak foar dy is.","interest.email":"Dyn e-mailadres","interest.which":"Hokker test?","interest.alpha":"Sletten alfa: betiid, rûch, in soad feroarings","interest.beta":"Beta: stabiler, letter","interest.both":"Beide, wat earst komt","interest.submit":"Set my op de list","interest.thanks":"Tank! Do stiest op de list.","licence.title":"AI-gile: bedriuwslisinsje","licence.description":"AI-gile brûke yn dyn bedriuw? Freegje in fergese bedriuwslisinsje oan.","licence.h1":"📜 Bedriuwslisinsje","licence.lede":"AI-gile brûke op it wurk? Fertel ús wa't do bist en wat do dochst. As it wat goeds docht, is de lisinsje fergees.","licence.company":"Bedriuw","licence.website":"Webside","licence.what":"Wat do dochst","licence.how":"Hoe't it de wrâld helpt","licence.email":"E-mail","licence.submit":"Oanfreegje","licence.thanks":"Tank! Wy antwurdzje per e-mail.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles stil","status.intro":"Wurket AI-gile no? Dizze side kontrolearret elke 5 minuten de webside, it dielen fan boerden, oproppen en de download.","status.up":"Wurket (antwurde yn {ms} ms)","status.slow":"Antwurde net by de lêste kontrôle, besiket it wer","status.down":"Plat: antwurde net by de lêste twa kontrôles","status.svc.web":"Webside","status.svc.web.offers":"Dizze side: wat AI-gile is, en it belangstellingsformulier","status.svc.boards":"Boerden diele","status.svc.boards.offers":"Iepenbiere boerden, berjochten tusken freonen en útnoegings","status.svc.calls":"Oproppen","status.svc.calls.offers":"Lûd, fideo en skerm diele yn AI-gile","status.svc.download":"Download","status.svc.download.offers":"De Windows-ynstallaasje en útnoegingskeppelings","status.checking":"Kontrolearje…","status.offline":"Kin de statustsjinst no net berikke (besykje it wer)","status.updated":"bywurke {ago}","status.justNow":"krekt no","status.min":"{n} min lyn","status.hours":"{n} oere lyn","status.days":"{n} d lyn","privacy.title":"AI-gile: wat wy bewarje","privacy.h1":"Wat wy bewarje","privacy.lede":"Koartsein: allinnich wat do ús stjoerst, en net lang.","privacy.only":"Allinnich wat do ús stjoerst: wat do yn in formulier typst, lykas dyn e-mailadres. Fierder neat oer dy.","privacy.sealed":"It wurdt fersegele, sadat ús server it net lêze kin: yn dyn browser, foardat it fuortgiet (by in âldere browser, op it momint dat it oankomt). Allinnich ús eigen boerd kin it iepenje.","privacy.server":"It wurdt fan 'e server wiske sa gau as it ús boerd berikt. Wat der nei 30 dagen noch stiet, wurdt dochs wiske.","privacy.board":"Wy bewarje it op ús boerd allinnich oant wy dy antwurde ha, dêrnei wiskje wy it dêr ek.","privacy.none":"Gjin trackers, gjin cookies, gjin analytics.","privacy.local":"Dyn taal en dyn kar foar ljocht of tsjuster bliuwe yn dyn eigen browser. Se wurde nea nei ús stjoerd.","privacy.ask":"Wolsto dat it earder fuort is? Antwurdzje op ús e-mail en sis it mar.","live.h2":"Sjoch it boud wurde, live","live.caption":"Elke kaart is ferburgen: do sjochst de foarm fan it wurk, net de wurden.","live.watching.one":"live: {n} sjocht","live.watching.other":"live: {n} sjogge","live.last.now":"Lêste kaart krekt ferpleatst","live.last.min.one":"Lêste kaart {n} min lyn ferpleatst","live.last.min.other":"Lêste kaart {n} min lyn ferpleatst","live.last.hour.one":"Lêste kaart {n} oere lyn ferpleatst","live.last.hour.other":"Lêste kaart {n} oeren lyn ferpleatst","live.last.day.one":"Lêste kaart {n} dei lyn ferpleatst","live.last.day.other":"Lêste kaart {n} dagen lyn ferpleatst","live.offline":"It live-boerd nimt efkes in azem. Sjoch gau wer.","live.cols":"Backlog|Te dwaan|Dwaande|Team kontrolearret|Foar dy om te test|Foar it team|Klear"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegearre."]},{"n":2,"texts":["Robots wurkje.","Aginten, oarderlik.","Ideeën, boud."]},{"n":3,"texts":["Kanban foar robots.","Ideeën wurde funksjes.","Fergees agintkanban."]},{"n":5,"texts":["Kanbanboerd rinne troch aginten.","Do skriuwst, aginten bouwe.","Fergees, lokaal, getest, in bytsje gek."]},{"n":8,"texts":["In fergees kanbanboerd dêr't AI-aginten wurkje.","Skriuw in idee. Aginten bouwe it. Do aksepteart.","Agile foar ien minske en in soad geduldige robots."]},{"n":13,"texts":["In kanbanboerd op dyn kompjûter dêr't AI-aginten de kaarten oppakke en útfiere.","Skriuw in idee. In team fan aginten bout it. In tester kontrolearret it.","Fergees, gjin akkounts, gjin trackers: in boerd, in pear robots, en do as baas."]},{"n":21,"texts":["AI-gile is in kanbanboerd om mei AI-koadeaginten te wurkjen. Se pakke de kaarten op; do test se en aksepteart se.","Elk projekt krijt in lieder en in team fan AI-aginten. Kommentearje op hokker kaart ek en it team giet oan it wurk.","In fergees, persoanlik taakboerd dat op dyn eigen kompjûter rint. De wurkers binne robots. Dejinge dy't ja seit, bist do."]},{"n":34,"texts":["Do set ideeën op in boerd. In team fan AI-aginten makket der wurkjende funksjes fan, test se en jout se werom mei stappen om út te probearjen. Neat telt as klear oant do it seist.","AI-gile is in selsmakke kanbanboerd dat Rich boude mei in soad help fan de aginten dy't it no beheart. It is fergees, rint op dyn kompjûter en wurdt mei freonen dield, net ferkocht.","Stel dy in gewoan kanbanboerd foar, mei kolommen fan Backlog oant Klear, útsein dat de kaarten oppakt wurde troch AI-aginten. Se melde foarútgong, stelle fragen as se fêst sitte, en wachtsje altyd op dyn tommen omheech."]},{"n":55,"texts":["AI-gile is in kanbanboerd wêrfan it team út AI-aginten bestiet. Elk projekt hat in lieder dy't it wurk plant en helpers dy't it bouwe. As in funksje klear is, besiket in AI-tester it út en makket in skermôfbylding, dan komt it op dyn steapel telâne. Akseptearje it, of kommentearje en se wurkje it nei.","It begûn as ien minske syn manier om in soad AI-koadesesjes tagelyk by te hâlden, en groeide út ta in echt boerd. It rint op dyn masine, hat gjin akkount nedich en hat gjin trackers. It is fergees foar freonen en nijsgjirrigen. It is ek net ôf, dus rekkenje op rûge rânen en no en dan in ferrassing.","Dit is de earlike ferzje. Do moatst noch altyd de ideeën hawwe, en do moatst de resultaten noch altyd kontrolearje. Wat AI-gile docht is alles dêrtusken: it hâldt de kaarten op oarder, wekket de krekte agint as do kommentearrest, lit presys sjen wat feroare is, en set it alles op ien koarte steapel foar dy."]},{"n":89,"texts":["AI-gile is in fergees kanbanboerd dat do op dyn eigen kompjûter rinne litst. Yn plak fan minsken hat elk projekt in team fan AI-aginten: in lieder dy't dyn ideeën omsette yn kaarten en in plan, en helpers dy't de kaarten yn folchoarder fan wichtichheid oppakke. As der wat boud is, folget in AI-tester de teststappen en lit dy sjen wat er seach. Dan wachtet it op ien steapel mei de namme Foar dy. Do aksepteart it, of do kommentearrest en it team besiket it noch ris. Neat komt ea by Klear sûnder dy.","Inkelde funksjes dy't do miskien net ferwachtest. In nachtwacht hâldt de kolom Te dwaan fol wylst do sliepst, mei kaarten dêr't gjin antwurd fan dy foar nedich is. In tokenteller lit sjen hoefolle de aginten hjoed en dizze wike brûkt hawwe, en de Gjin-token-modus seit harren dat se ophâlde moatte mei útjaan. Do kinst freonen berjochten stjoere, en priveeberjochten binne end-to-end fersifere. It boerd praat sa'n 120 talen, ûnder oaren Nederlânsk, Flaamsk, piraat en Klingon. Neat dêrfan kostet in sint, en gjinien besiket it dy oan te smeren.","AI-gile is in lyts, persoanlik projekt, gjin bedriuw. Rich woe foar ferskate AI-koadeprojekten soargje sûnder elke app iepen te dwaan om te sjen hoe't it derfoar stie, dus hy en de aginten boude dêr in boerd foar, en brûkten it boerd doe om de rest sels te bouwen. It sit yn sletten pre-alfa, wat betsjut dat it wurket, foar it grutste part, foar in hânfol freonen. Der is gjin prizenside, gjin nijsbrief en gjin groeiplan. As it nuttich klinkt, kinst freegje om it út te probearjen as it wat fierder iepengiet."]},{"n":144,"texts":["AI-gile is in kanbanboerd foar ien minske en in soad AI-aginten. It rint op dyn eigen kompjûter en is folslein fergees. Do foegest projekten ta, en elk projekt krijt in lieder en in lyts team. Do praatst mei de lieder, in bytsje as op Discord, en beskriuwst in idee; de lieder makket der kaarten en in plan fan, en wachtet dan oant do op Go drukst. It team wurket de kaarten ôf op folchoarder fan wichtichheid, mei in ienfâldige kommandorigel makke foar taalmodellen. Foardat der wat by dy weromkomt, folget in AI-tester de stappen yn in kopy fan de app en foeget in skermôfbylding ta. Klear wurk komt op dyn steapel mei de feroare bestannen en de diff. Do aksepteart it, of do litst in kommentaar efter en it team wurdt wekker en besiket it opnij. Allinnich do kinst in kaart nei Klear ferpleatse.","In dei mei AI-gile, rûchwei. Jûns litst in pear kommentaren efter: dizze knop stiet op it ferkearde plak, dy list moat sortearre wurde, koe der ek in tsjuster tema komme. Do giest op bêd. De aginten lêze de kommentaren, meitsje de feroarings, testen se en jouwe se werom. As Te dwaan leech rekket, folt de nachtwacht it út de backlog oan mei kaarten dêr't gjin antwurd fan dy foar nedich is. Moarns leit der ien koarte steapel: in pear fragen en in pear dingen om út te probearjen, elk mei stappen dy't in sliepeachtich minske folgje kin en in skermôfbylding fan it wurkjen. Do klikst der troch, aksepteart de goede en stjoerst de rest werom. In tokenteller lit sjen wat it allegear brûkt hat, en de Gjin-token-modus is der foar de mager wiken. Dan ytst dyn moarnsiten, dêr't de aginten noch net mei helpe kinne.","Earst, wat AI-gile net is. It is gjin startup, it is net te keap, en gjinien sammelet dyn gegevens. It is in fergees boerd dat op dyn kompjûter rint, sûnder akkounts, sûnder trackers en sûnder cookies. Wat it wol is: ien oarderlike plak om alle AI-koadeprojekten tagelyk te sjen, mei in team fan aginten dat de kaarten docht en do dy de besluten nimst. It smelt besibbe kaarten gear, makket wazige titels goed, en hâldt yn de gaten hoe licht de koade bliuwt. It praat sa'n 120 talen, fan Nederlânsk en Flaamsk oant piraat en Klingon. Freonen kinne inoar berjochten stjoere, privee en fersifere. It is boud troch Rich en in grut tal geduldige aginten, meast troch himsels te brûken. It sit yn sletten pre-alfa, dus it is op plakken noch rûch. As it dy leuk klinkt, freegje it freonlik en miskien komst der betiid yn."]}],"quips":{"1":"Ien wurd. Dryst. Miskien te dryst.","3":"Trije wurden. Al earliker as de measte produktsiden.","8":"Acht wurden. Noch koarter as in stânddei-oerlis.","21":"De lingten binne trouwens story points. Fansels binne se dat.","55":"Fiifenfyftich wurden. Twa kaarten binne klear wylst do dit lies.","144":"Dat is de lange. Der is gjin 233. De aginten binne op bêd."}},"timeline":{"first-idea.name":"It earste idee","first-idea.line":"It allereerste petear, foardat der ien rigel koade wie.","first-board.name":"Earste boerd","first-board.line":"In boerd dat syn eigen bou byhâldt: kaarten, kolommen, slepe en delsette, projekten.","team-roles.name":"Team en rollen","team-roles.line":"Agintprofilen, teamsjablonen, romtes en wa't wat docht.","install.name":"Ynstallaasje en útjeften","install.line":"In zip dy't in freon ynstallearje kin, selsbywurkjen, kanalen en weromdraaie.","usage-saver.name":"Gebrûksbesparring","usage-saver.line":"Mjit wat runs kostje, hâld de koade licht, bewarje dyn limyt.","friends.name":"Freonen en dielen","friends.line":"Priveeberjochten, in forskoft relay, útnoegingen, rollen en dielde projekten.","languages.name":"Talen","languages.line":"Elke skermtekst yn in taalbestân, mei Nederlânsk en Flaamsk earst.","ai-tester.name":"AI-tester","ai-tester.line":"In tester kontrolearret elke oerdracht earst en lit sjen wat er seach.","website.name":"De webside","website.line":"aigile.lol, de teaser en dizze tiidline.","streaming.name":"Chat en streamen","streaming.line":"Discord, Twitch, OBS, streamermodus, GIF's en emoji's.","no-ai.name":"Edysje sûnder AI","no-ai.line":"In boerd foar minsken dy't koadzje sûnder AI, en iepenbiere boerden.","night-watch.name":"Nachtwacht","night-watch.line":"In wachter en Scrum Master hâlde de teams op taak wylst do sliepst.","p-more.name":"Al it oare","p-more.line":"Lytsere ideeën dy't noch op har bar wachtsje.","p-android.name":"Tillefoan en Android","p-android.line":"Berik dyn boerd fan in tillefoan, dêrnei in eigen Android-app.","p-release.name":"Alfa en fierder","p-release.line":"Sletten alfa, de libbene side, dêrnei beta.","p-languages.name":"Mear talen","p-languages.line":"130 talen, en in ûnderdompelingsmodus foar wa't in taal leart.","p-engines.name":"Mear AI-motoren","p-engines.line":"Kies Claude, Codex, Gemini, Copilot of Cursor foar elke agint.","p-pro.name":"Profesjonele praktyk","p-pro.line":"Risikolabels, gearfoegingspoarten, ynsidintkaarten en leuningen.","p-self.name":"Soargje foar dy","p-self.line":"Wurch-modus, selssoarch-herinneringen en 4:20.","p-servers.name":"Servers en skaal","p-servers.line":"Globale serverynstellings, rollen en planne foar groei.","p-livestream.name":"Streamingekstra's","p-livestream.line":"Twitch-chat, eigen emoji's en in iepenbier live byld."},"words":{"button":"📖 Fakwurden","h":"📖 Wurden útlein","intro":"De wurden dy't do tsjinkomst yn AI-gile, yn ienfâldige taal: it bouwen, it feilich feroarjen, it draaiende hâlden foar de minsken dy't it brûke, en gearwurkjen as team mei AI.","search":"In wurd sykje…","none":"Gjin wurd dat hjirby past.","close":"Slute","count":{"one":"{count} wurd","other":"{count} wurden"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Bouwe"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Feilich feroarje"},{"id":"run","name":"🛎️ In tsjinst draaiende hâlde"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ideeën en wurk dat noch net pland is. Dêr wurdt neat oan wurke oant it nei Te dwaan giet."},{"id":"sprint","g":"agile","word":"Sprint","text":"In koart stik wurk (faak in wike of twa) mei in ôfpraat set kaarten dy't klear moatte.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"In flugge ynchecking: wat elk teamlid die, wat er folgjende docht, en wat him tsjinhâldt.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"In boerd mei kolommen (Te dwaan, Dwaande, Klear) dêr't kaarten fan links nei rjochts gean as it wurk foarútgiet."},{"id":"wip","g":"agile","word":"WIP-limyt","text":"Work in progress: it maksimum oantal kaarten yn in kolom, sadat it team dingen ôfmakket foardat er mear begjint.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"De koarte kontrôlelist fan it team foar wat „klear“ betsjut, lykas test en útlein, foardat in kaart nei dy ta giet. Syn twilling, de Definition of Ready, seit wannear't in kaart dúdlik genôch is om te begjinnen.","also":["Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"In weromblik op hoe't it team wurket, om it iens te wurden oer ien ding dat better kin. Yn AI-gile stelt in retro in feroaring foar yn de wurkwize fan it team, en do seist Go of Noch net.","also":["retro's","retrospektive","retrospektiven"]},{"id":"swarm","g":"agile","word":"Swerm","text":"Alle hannen oan dek: elk team lit oar wurk lizze om te helpen by ien driuwend projekt oant it oplost is. Oare projekten wachtsje sa lang.","also":["swarm","swarming","swermje"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Dejinge dy't it wurk geande hâldt: sjocht fêstsittende kaarten, jout de teams in dúdsje en herinnert dy oan wat der wachtet. Yn AI-gile docht de Lead Scrum Master dat oer alle projekten hinne.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"De map fan it projekt mei koade en de folsleine skiednis fan commits, meast ek op GitHub bewarre.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"In aparte line fan wurk yn de koade, sadat wizigingen makke wurde kinne sûnder de haadferzje oan te rekken.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"In bewarre momintopname fan de koade, mei in koart notysje fan wat feroare is. Do kinst altyd werom nei ien.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Bewarre momintopnames (commits) fan dizze kompjûter nei GitHub stjoere, sadat se bewarre en dield binne."},{"id":"merge","g":"build","word":"Merge","text":"De wizigingen fan in branch wer yn de haadferzje gearfoegje."},{"id":"pr","g":"build","word":"Pull request","text":"Freegje om de wizigingen fan in branch te kontrolearjen en yn de haadferzje gear te foegjen.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"De koade opromje sûnder te feroarjen wat er docht: lytsere bestannen, dúdlikere nammen, minder werhelling."},{"id":"bug","g":"build","word":"Bug","text":"Wat net wurket sa't it moat.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"In twadde pear eagen: in oare AI kontrolearret it wurk fan elke kaart foardat it by dy oankomt, sadat der minder flaters trochglippe.","also":["code review","koadereview"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"In klear stik wurk besykje om te kontrolearjen dat it docht wat frege is, foardat do it akseptearrest.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Koart foar it Ingelske quality assurance, kwaliteitsfersekering: de automatyske kontrôles dy't rinne foardat der wat live giet. As QA read is, is der wat mislearre, en it kin net live oant dat reparearre is.","also":["kwaliteitskontrôle","kwaliteitskontrôles","kwaliteitsfersekering"]},{"id":"testpile","g":"test","word":"Teststapel","text":"De kleare kaarten dy't wachtsje oant do se útprobearrest, de iene nei de oare. Akseptearje der ien of stjoer him werom mei in notysje, en de folgjende komt.","also":["teststapels"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"In nije ferzje live sette, bygelyks op in server dêr't minsken it brûke."},{"id":"release","g":"change","word":"Release","text":"In beneamde bondel klear wurk dat tegearre live giet, mei koarte notysjes oer wat der feroare is. 🚀 Releases skriuwt de notysjes út de kleare kaarten.","also":["releases","ferzje","ferzjes"]},{"id":"rollback","g":"change","word":"Rollback","text":"Werom nei de lêste ferzje dy't wurke, as in nije swierrichheden jout. Yn AI-gile makket dat in kontrôlelist fan de weromdraaistappen dy't by elke wiziging opskreaun binne.","also":["weromdraaie","weromdraaid","rollbacks"]},{"id":"live","g":"change","word":"Live","text":"De echte ferzje dy't minsken brûke, yn tsjinstelling ta in kopy om dingen út te probearjen. Untwikkelers neame it ek produksje.","also":["produksje","production"],"noTip":1},{"id":"change","g":"change","word":"Wiziging","text":"In plande wiziging oan iets dêr't minsken op rekkenje, earst opskreaun: wat, wêrom, it risiko, wannear en hoe't it weromdraaid wurdt. Begjin der ien mei 🔀 Wiziging oanfreegje.","also":["wizigingen","wizigingsfersyk","wizigingsfersiken"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Iets dat mis gean kin, mei in skoare foar hoe wierskynlik en hoe slim it wêze soe. ⚠️ Risiko's hâldt se yn ien list, heechste skoare foarop, elk mei in datum om der nochris nei te sjen.","also":["risiko's","risikolist","risikoregister"]},{"id":"chgwin","g":"change","word":"Wizigingsfinster","text":"De tiden dat wizigingen live gean meie, lykas in stille tiisdeitejûn. Bûten in finster kin in wizigingskaart net ôfmakke wurde, útsein by in need.","also":["wizigingsfinsters"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"In flugge stimming krekt foardat in wiziging live giet: elkenien dy't goedkarre moat, seit Go of No go. It giet allinnich troch as se it iens binne.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Goedkarring","text":"Wachtsje op in ja foardat it wurk begjint. In kaart dy't in freon oanmakket, of in wiziging, wachtet yn ✅ Goedkarrings oant do him goedkarst of ôfwiist.","also":["goedkarrings","goedkarren"]},{"id":"quiettime","g":"change","word":"Stille tiid","text":"In skoft, lykas in stream, in demo of de nacht, dat der neat live giet. De teams wurkje en teste troch, mar live gean wachtet oant it foarby is. Oars wurdt dat in change freeze neamd.","also":["stille tiden","change freeze","wizigingsstop"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Tsjinst","text":"Iets datsto boud hast dêr't minsken op rekkenje, lykas in website of in app, dat ûnderhâlden wurdt sadat it bliuwt wurkjen. Finkje „Dit projekt is in tsjinst“ oan en sis wat er biedt, wa't him brûkt en wa't on-call is.","also":["tsjinsten","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Beskikberenskontrôle","text":"In automatyske kontrôle, om de pear minuten, oft dyn tsjinst noch antwurdet. As dy ferskate kearen efterinoar mislearret, iepenet AI-gile sels in incidintkaart.","also":["beskikberens","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Statusside","text":"In iepenbiere side dy't sjen lit oft in tsjinst wurket (grien, oranje of read), mei it lêste nijs, sadat de brûkers sels sjen kinne ynstee fan te freegjen.","also":["statussiden","status page"]},{"id":"desk","g":"run","word":"Servicebalie","text":"It plak dêr't fragen en meldingen fan de minsken dy't dyn tsjinst brûke binnenkomme. AI-gile sortearret elk as fersyk, incidint of idee, en seit it as it liket op wat dat al earder meld is.","also":["servicebalies","balie","service desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Servicefersyk","text":"Immen dy't om wat gewoans freget, lykas in nij akkount of in bytsje help, yn stee fan te melden dat der wat stikken is. It wachtet op syn bar; in incidint giet foar.","also":["servicefersiken"]},{"id":"incident","g":"run","word":"Incidint","text":"Iets dat no op dit stuit stikken is foar de minsken dy't it brûke, lykas in website dy't plat leit. In 🔥 incidintkaart giet foar de rige: it wer oan it wurk krije komt earst.","also":["incidinten","incident","steuring"]},{"id":"major","g":"run","word":"Major incident","text":"In grut incidint: in soad minsken rekke, of jild of gegevens yn gefaar. Ien knop set alle teams derop (swerm), makket wa't on-call is wekker en freget elke 30 minuten om in statusupdate.","also":["grut incidint","grutte incidinten","major incidents"]},{"id":"oncall","g":"run","word":"On-call","text":"Dejinge wêze dy't reagearret as der wat stikken giet, ek nachts. Elke tsjinst hat in on-call teamlid dat by syn incidinten as earste wekker makke wurdt.","also":["on call","wacht","wachttsjinst"]},{"id":"replyby","g":"run","word":"Reaksjetiid","text":"Hoe lang in kaart op in earste antwurd wachtsje mei, bygelyks in oere foar in incidint. Dêrnei krijt er in reade klok, sadat neat stil fergetten wurdt. Hjit ek wol reaksjedoel.","also":["reaksjetiden","antwurdtermyn","reaksjedoel"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"In koarte weromblik nei in incidint: wat der barde, wat holp en wat der feroarje moat, sûnder ien de skuld te jaan. In incidint kin net sletten wurde sûnder ien.","also":["post-mortems","postmortem","neibeskôging"]},{"id":"problem","g":"run","word":"Probleem","text":"De ferburgen oarsaak efter ien of mear incidinten. In 🧩 probleemkaart bondelet incidinten dy't hieltyd weromkomme, sadat de oarsaak fûn en foar goed reparearre wurdt.","also":["problemen"],"noTip":1},{"id":"rootcause","g":"run","word":"Grûnoarsaak","text":"De echte reden dat der wat stikken gie, net allinnich watsto mis gean seachst. Reparearje de grûnoarsaak en it incidint komt net mear werom.","also":["grûnoarsaken","haadoarsaak","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"In manier om dingen draaiende te hâlden oant de echte reparaasje klear is, lykas wat opnij starte as it fêstrint. It stiet op de probleemkaart, sadat net elkenien it opnij útfine moat.","also":["workarounds","needoplossing","tydlike oplossing"]},{"id":"knownerror","g":"run","word":"Bekende fout","text":"In probleem dêr't de oarsaak fan begrepen is en dat in workaround hat, mar dat noch net reparearre is. 🧩 Bekende fouten set se op in rige, sadat elkenien de workaround brûkt ynstee fan wer te sykjen.","also":["bekende fouten","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Stap-foar-stap-ynstruksjes om in bekend soarte swierrichheid op te lossen, sadat it elke kear op deselde manier en fluch dien wurdt. Nei in grut incidint kin it team der ien foarstelle dêrsto OK op seist.","also":["runbooks","draaiboek"]},{"id":"ci","g":"run","word":"Konfiguraasje-item","text":"Ien ding dêr't dyn tsjinst fan ôfhinget, lykas in server, in domein, in sertifikaat, in kaai of in leveransier. 🗂️ Konfiguraasje-items set se per tsjinst op in rige, sadat do sjochst wat in incidint rekket en wat fernijd of back-upt wurde moat.","also":["konfiguraasje-items","configuration item","CI"]},{"id":"expiry","g":"run","word":"Ferrindatum","text":"AI-gile hâldt datums yn 'e gaten, lykas wannear't in sertifikaat of in domein ferrint. Binnen 30 dagen foar de datum makket it ien kaart om it te fernijen, sadat neat ûnferwachts ophâldt mei wurkjen.","also":["ferrindatums","ferrinnen","ferrintoesjoch"]},{"id":"backup","g":"run","word":"Reservekopy","text":"In bewarre kopy fan dyn gegevens fan earder, om op werom te fallen as der wat kwyt rekket of skansearre wurdt. AI-gile makket alle dagen in reservekopy fan dyn boerden.","also":["reservekopyen","backup","back-up"]},{"id":"restore","g":"run","word":"Weromsette","text":"Gegevens weromhelje út in reservekopy. In reservekopy telt pas echt as do witst dat er weromset wurde kin, dus it is de muoite wurdich om dat sa no en dan te probearjen.","also":["weromset","weromsetting","restore"]},{"id":"svcreview","g":"run","word":"Tsjinstreview","text":"In weromblik op ien moanne fan in tsjinst: incidinten iepene en reparearre, hoe fluch minsken in antwurd krigen, beskikberens en brûkte tokens. De Moanlikse review lit it foar elke tsjinst sjen.","also":["tsjinstreviews","moanlikse review","moanlikse reviews"]},{"id":"accessreview","g":"run","word":"Tagongskontrôle","text":"Elke 90 dagen neigean wa't der noch yn kin: dielkeppelings, rollen fan freonen en bewarre geheimen. Do hâldst of smytst elk fuort, sadat âlde tagong net bliuwt hingjen.","also":["tagongskontrôles","access review"]},{"id":"improvements","g":"run","word":"Ferbetterlist","text":"Alles wêr't it team better yn wurde wol, op ien plak: retrofoarstellen, reviewaksjes en probleemreparaasjes, elk mei syn status. Do fynst it ûnder 📈 Ferbetteringen.","also":["ferbetterlisten","ferbetteringen"]},{"id":"tokencap","g":"run","word":"Tokenlimyt","text":"In moanlikse limyt op de tokens dy't de aginten fan in tsjinst brûke meie. By 80% krijst in warskôging; by 100% wachtet harren eftergrûnwurk oant de folgjende moanne of oant do de limyt ferheechst.","also":["tokenlimiten","moanlikse tokenlimyt","token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agint","text":"In AI dy't sels oan in taak wurket: lêst de koade, makket wizigingen, docht kontrôles en makket ferslach.","also":["aginten"]},{"id":"token","g":"ai","word":"Token","text":"De ienheid dêr't AI-gebrûk yn teld wurdt: sawat in pear letters tekst lêzen of skreaun. Minder tokens, mear oer fan dyn abonnemint.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"In lyts kommando dat op in bepaald momint fansels rint, bygelyks as in AI-sesje begjint, sadat it team dyn reaksjes heart.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
